SoundCmd	;Send command d0 to the sound driver (SndDriver)
	jsr	(SndDriver).l
	bcc.w	.exit
	nop
.exit
	rts

UpdateCwdExcite	;Called once per second. Track peak and running total of crowd excitement, then decay the level by 1
	move.w	(CwdExciteLvl).w,d0
	cmp.w	(MaxCwdExciteLvl).w,d0
	bls.w	.less
	move.w	d0,(MaxCwdExciteLvl).w	;new peak
.less
	ext.l	d0
	add.l	d0,(SumCwdExciteLvl).w	;running total
	addq.w	#1,(NumCwdExciteLvl).w	;sample count
	subq.w	#1,(CwdExciteLvl).w	;decay
	bpl.w	.ex
	clr.w	(CwdExciteLvl).w
.ex
	rts

updatesound	;Move the crowd noise volume (psg noise channel, asv) toward crowdlevel. Called from DoGameFrame
	move.w	(crowdlevel).w,d0
	asl.w	#3,d0
	addi.w	#$400,d0
	cmp.w	#$EFF,d0
	bls.w	.ip
	move.w	#$EFF,d0
.ip
	moveq	#$28,d2
	sub.w	(asv).w,d0
	cmp.w	d2,d0
	bgt.w	.iasv
	neg.w	d2
	cmp.w	d2,d0
	bge.w	.non
.iasv
	add.w	d2,(asv).w
	bpl.w	.non
	clr.w	(asv).w
.non
	move.b	#$C8,(VDP_PSG).l
	move.b	#1,(VDP_PSG).l
	move.b	(asv).w,d0
	eori.b	#$F,d0
	ori.b	#$F0,d0
	move.b	d0,(VDP_PSG).l
	rts

CheckLateGameSong	;Called once per second. 3rd period: choose and play a song once at the random trigger time set by ResetClock
	cmpi.w	#2,(gsp).w
	bne.w	.x
	btst	#4,(gmode).w
	bne.w	.x
	move.w	(gameclock).w,d0
	cmp.w	(periodendtime).w,d0
	bgt.w	.x
	st	(periodendtime).w	;high byte $FF: trigger goes negative, fires once
	move.w	(HomeTeam).w,(HmTeam).w
	move.w	#5,(SongIndex).w
	jsr	(ChooseSong).l
	move.w	(SongNum).w,-(sp)
	jsr	(song).l
.x
	rts

sfx	;Play sound effect number, one word passed on stack: through SfxTable to a sound driver song (command 4)
	movem.l	d0-d7/a0-a6,-(sp)
	clr.l	d0
	move.w	$40(sp),d0	;$40 = 16*4
	bpl.w	sfxplay
	movem.l	(sp)+,d0-d7/a0-a6
	move.l	(sp),2(sp)
	addq.w	#2,sp
	rts

sfxplay	;Play sound d0 ($32-$55 are songs, PlayingSong; below, SfxTable). Sound $B / $C: a nop. song branches here
	cmp.w	#$B,d0
	beq.w	.nop
	cmp.w	#$C,d0
	bne.w	.chksong
.nop
	nop
.chksong
	cmp.w	#$55,d0
	bgt.w	.done
	cmp.w	#$32,d0
	blt.w	.sfx
	move.w	d0,(PlayingSong).w
	bra.w	.play
.sfx
	movea.l	#SfxTable,a1
	tst.b	(a1,d0.w)
	bmi.w	.done
	cmpi.b	#$26,(a1,d0.w)
	bne.w	.chklast
	movem.l	d0-d4/a0-a1,-(sp)
	movea.l	#SndSeqPtr,a0
	movea.w	#(SndSeqId-M68K_RAM),a1
	move.w	#7,d4
	clr.w	d3
.slot
	cmpi.l	#$FFFFFFFF,(a0)
	beq.w	.nextslot
	cmpi.w	#$31,(a1,d3.w)
	ble.w	.nextslot
	move.w	(a1,d3.w),d1
	move.w	#5,d0
	move.w	#$FFFF,d2
	jsr	(SndDriver).l
	bra.w	.stopped
.nextslot
	addq.w	#4,a0
	addq.w	#2,d3
	dbf	d4,.slot
.stopped
	movem.l	(sp)+,d0-d4/a0-a1
.chklast
	cmp.w	#$B,d0
	beq.w	.lookup
	cmp.w	#$C,d0
	beq.w	.lookup
	move.w	d0,(lastsfx).w
.lookup
	move.b	(a1,d0.w),d0
.play
	ext.w	d0
	move.w	d0,d1
	move.w	#4,d0
	move.w	#$FFFF,d2
	move.w	#$7F,d3
	move.w	#$100,d4
	jsr	(SoundCmd).l
.done
	movem.l	(sp)+,d0-d7/a0-a6
	move.l	(sp),2(sp)
	addq.w	#2,sp
	rts

SfxTable	;Sound driver song for sound effects 0-$31 (sfx), $FF = none. $26 first stops the songs above $31
	dc.b	$26,$1C,$1D,$17,$16,$FF,$09,$25	;sounds $00-$07
	dc.b	$04,$5A,$5B,$10,$1E,$13,$20,$0E	;sounds $08-$0F
	dc.b	$0B,$0B,$0B,$0B,$08,$08,$08,$08	;sounds $10-$17
	dc.b	$08,$08,$08,$08,$21,$23,$23,$22	;sounds $18-$1F
	dc.b	$18,$15,$15,$15,$25,$04,$04,$04	;sounds $20-$27
	dc.b	$18,$18,$18,$18,$11,$1A,$1A,$5C	;sounds $28-$2F
	dc.b	$5D,$2E	;sounds $30-$31

song	;Play song number, one word passed on stack: songs 0-3 through StartSong, the rest through sfxplay
	movem.l	d0-d7/a0-a6,-(sp)
	clr.l	d0
	move.w	$40(sp),d0	;$40 = 16*4
	bmi.w	.none
	cmp.w	#$32,d0
	blt.w	.0
	cmp.w	#$55,d0
	bgt.w	.0
	jsr	(stop_current_song).l
	move.w	d0,(PlayingSong).w
.0
	cmp.w	#3,d0
	ble.w	.1
	bra.w	sfxplay
.1
	jsr	(StartSong).l
.none
	movem.l	(sp)+,d0-d7/a0-a6
	move.l	(sp),2(sp)
	addq.w	#2,sp
	rts

StartSong	;Stop the song, then song d0 (command 4, tempo $100)
	tst.w	d0
	bmi.w	.0
	movem.l	d0-d7/a0-a6,-(sp)
	bsr.w	stop_current_song
	move.w	d0,(PlayingSong).w
	move.w	d0,d1
	move.w	#4,d0
	move.w	#$FFFF,d2
	move.w	#$7F,d3
	move.w	#$100,d4
	jsr	(SoundCmd).l
	movem.l	(sp)+,d0-d7/a0-a6
.0
	rts

stop_current_song	;Stop the song in progress (PlayingSong, sound driver command 5)
	movem.l	d0-d7/a0-a6,-(sp)
	move.w	#5,d0
	move.w	(PlayingSong).w,d1
	bmi.w	.0
	move.w	#$FFFF,d2
	jsr	(SoundCmd).l
	move.w	#$FFFF,(PlayingSong).w
.0
	movem.l	(sp)+,d0-d7/a0-a6
	rts

